document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("discoverSearch"),t=document.getElementById("clearFilters");e?.addEventListener("keydown",t=>{"Enter"===t.key&&(t.preventDefault(),e.form?.submit())}),t?.addEventListener("click",()=>{t.dataset.clearUrl&&(window.location.href=t.dataset.clearUrl)});const n=document.getElementById("filtersToggleBtn"),d=document.getElementById("discoverFilters");n?.addEventListener("click",()=>{const e=!d.classList.contains("open");d.classList.toggle("open",e),n.setAttribute("aria-expanded",String(e))})});